// Pobb Enhancer content script: makes items and gems on pobb.in build pages
// open a prefilled pathofexile.com/trade search on click.
(() => {
  const api = globalThis.browser ?? globalThis.chrome
  const ITEM_SEL = '.inventory img.item'
  const GEM_SEL = '[data-gem-id]'

  // content-lib.js (generated by scripts/build.mjs from src/lib) runs first.
  const lib = async () => globalThis.PobbEnhancerLib

  // pobb.in is a single-page app, so cache the build per path.
  const builds = new Map()
  function buildPath () {
    const m = /^(\/u\/[^/]+)?\/[A-Za-z0-9_-]{6,}/.exec(location.pathname)
    return m ? m[0] : null
  }
  function loadBuild (path) {
    if (!builds.has(path)) {
      builds.set(path, (async () => {
        const res = await fetch(location.origin + path + '/xml')
        if (!res.ok) return null
        const xml = await res.text()
        if (!/<PathOfBuilding2?[\s>]/.test(xml)) return null
        const { parseBuildXml } = await lib()
        return parseBuildXml(xml)
      })().catch(() => null))
    }
    return builds.get(path)
  }

  async function activeBuild () {
    const path = buildPath()
    if (!path) return null
    const build = await loadBuild(path)
    return build && !build.isPoe2 ? build : null
  }

  // ---- UI: badge + toast ----------------------------------------------------
  let badge = null
  let badgeTarget = null
  function showBadge (el) {
    badgeTarget = el
    if (!badge) {
      badge = document.createElement('div')
      badge.className = 'pobb-enhancer-badge'
      badge.textContent = '⇄'
      badge.setAttribute('aria-hidden', 'true')
      document.body.appendChild(badge)
    }
    const r = el.getBoundingClientRect()
    badge.style.left = `${Math.round(r.right - 16)}px`
    badge.style.top = `${Math.round(r.top + 2)}px`
    badge.style.display = 'block'
  }
  function hideBadge () {
    badgeTarget = null
    if (badge) badge.style.display = 'none'
  }

  let toast = null
  let toastTimer = null
  function showToast (title, lines = [], isError = false) {
    if (!toast) {
      toast = document.createElement('div')
      toast.className = 'pobb-enhancer-toast'
      toast.setAttribute('role', 'status')
      toast.addEventListener('click', () => { toast.style.display = 'none' })
      document.body.appendChild(toast)
    }
    toast.replaceChildren()
    toast.classList.toggle('pobb-enhancer-error', isError)
    const t = document.createElement('div')
    t.className = 'pobb-enhancer-toast-title'
    t.textContent = title
    toast.appendChild(t)
    for (const line of lines) {
      const d = document.createElement('div')
      d.className = 'pobb-enhancer-toast-line'
      d.textContent = line
      toast.appendChild(d)
    }
    toast.style.display = 'block'
    clearTimeout(toastTimer)
    toastTimer = setTimeout(() => { toast.style.display = 'none' }, lines.length ? 8000 : 3500)
  }

  function report (res) {
    if (!res || res.error) {
      showToast('Pobb Enhancer: could not open trade', [res?.error || 'No response from the extension.'], true)
      return
    }
    const mods = res.total ? ` · ${res.matched}/${res.total} mod lines` : ''
    const title = `Trade opened: ${res.label} (${res.league})${mods}`
    const lines = []
    if (res.known === false) lines.push('Gem not found in the item list, searched by name as shown.')
    if (res.skipped?.length) {
      lines.push('Skipped (no trade stat):')
      for (const s of res.skipped.slice(0, 4)) lines.push('• ' + s)
      if (res.skipped.length > 4) lines.push(`• …and ${res.skipped.length - 4} more`)
    }
    showToast(title, lines)
  }

  // ---- click handling -------------------------------------------------------
  function targetOf (ev) {
    const el = ev.target instanceof Element ? ev.target : null
    if (!el) return null
    const img = el.closest(ITEM_SEL)
    if (img) return { kind: 'item', el: img }
    const gem = el.closest(GEM_SEL)
    if (gem) return { kind: 'gem', el: gem }
    return null
  }

  async function itemTextFor (img, build) {
    const { mapImagesToItems } = await lib()
    const all = [...document.querySelectorAll(ITEM_SEL)]
    const imgs = all.map(i => ({ slot: i.classList[1] || '', alt: i.getAttribute('alt') }))
    const texts = mapImagesToItems(build, imgs)
    return texts[all.indexOf(img)] || null
  }

  async function handle (target, background) {
    const build = await activeBuild()
    if (!build) return
    let msg
    if (target.kind === 'gem') {
      const d = target.el.dataset
      msg = { type: 'trade', kind: 'gem', background, gem: { name: target.el.textContent.trim(), level: d.gemLevel, quality: d.gemQuality } }
    } else {
      const text = await itemTextFor(target.el, build)
      if (!text) {
        showToast('Pobb Enhancer: could not find this item in the build', [], true)
        return
      }
      msg = { type: 'trade', kind: 'item', background, text }
    }
    try {
      report(await api.runtime.sendMessage(msg))
    } catch (e) {
      report({ error: e.message || String(e) })
    }
  }

  document.addEventListener('click', (ev) => {
    // Ctrl/Cmd+click is pobb.in's "open wiki"; leave modified clicks alone.
    if (ev.button !== 0 || ev.ctrlKey || ev.metaKey || ev.shiftKey || ev.altKey) return
    const target = targetOf(ev)
    if (!target) return
    ev.preventDefault()
    handle(target, false)
  })
  // Middle click opens the search in a background tab.
  document.addEventListener('auxclick', (ev) => {
    if (ev.button !== 1) return
    const target = targetOf(ev)
    if (!target) return
    ev.preventDefault()
    handle(target, true)
  })
  document.addEventListener('mousedown', (ev) => {
    if (ev.button === 1 && targetOf(ev)) ev.preventDefault() // no autoscroll
  })

  document.addEventListener('mouseover', (ev) => {
    const target = targetOf(ev)
    if (!target) { hideBadge(); return }
    badgeTarget = target.el
    activeBuild().then(build => { if (build && badgeTarget === target.el) showBadge(target.el) })
  })
  // Keep the badge on its item while the page scrolls.
  window.addEventListener('scroll', () => {
    if (badgeTarget && badge && badge.style.display === 'block') showBadge(badgeTarget)
  }, { passive: true, capture: true })

  // Mark the page so CSS can show pointer cursors, once we know it's a PoE1 build.
  function refreshMarker () {
    activeBuild().then(build => {
      document.documentElement.classList.toggle('pobb-enhancer-active', !!build)
    })
  }
  refreshMarker()
  let lastPath = location.pathname
  setInterval(() => {
    if (location.pathname !== lastPath) {
      lastPath = location.pathname
      refreshMarker()
    }
  }, 1000)
})()
